const Festval_serch_details = (props) => {
  const [defaultArea, area] = useState("전국");
  const defaultDate = "월별";

  const [isSelect,setIsSelect] = useState(0); // 드롭메뉴_셀렉트
  const [isCalender,setIsCalender] = useState(0); // 드롭메뉴_캘린더

  const onClickItem = (e) =>{
    setIsSelect(0);    
    //console.log(e.target.innerText);
    area(e.target.innerText);        
  }

  const onClickCheck = (e) =>{    
    //console.log(e.target.id);w
    let divIdValue = e.target.id;
    if(divIdValue === "class_ground"){
      if(setIsCalender === 1) return setIsCalender(0);
      else return setIsSelect(1);
    }
    else if(divIdValue ==="class_date"){
      console.log(setIsSelect.State);
      if(setIsSelect === 1){
        return setIsSelect(0);
      }
      else{
        return setIsCalender(1);
      }      
    }
    else{
      alert("잘못된 접근!");
    }
  }

  return(
    <div className='search_box'>
        <div className='search_class'>                     
          <button id='class_ground' className='select_button' onClick={onClickCheck}>{defaultArea}</button>
          <button id='class_date' className='select_button' onClick={onClickCheck}>{defaultDate}</button>                       
          <div id="select_hidden">
            <ul id="area_selete" style={{display: isSelect ? "block" : "none"}}>
              <li className="select_item" onClick={onClickItem}>전국</li>
              <li className="select_item" onClick={onClickItem}>서울</li>
              <li className="select_item" onClick={onClickItem}>인천</li>
              <li className="select_item" onClick={onClickItem}>대전</li>
              <li className="select_item" onClick={onClickItem}>대구</li>
              <li className="select_item" onClick={onClickItem}>광주</li>
              <li className="select_item" onClick={onClickItem}>부산</li>              
            </ul>
            <div id="date_calender" style={{display: isCalender ? "block" : "none"}}>
              <ul className="calender_date calender_years">
                <li className="calender_item years_item">{props.today}</li>                
              </ul>
              <ul className="calender_date">
                {[...Array(12)].map((t, idx) => {
                  return <li className="calendar_item" onClick={onClickItem}>{idx+1}월</li>
                })}
                {/* <li className="calender_item" onClick={onClickItem}>1월</li>
                <li className="calender_item" onClick={onClickItem}>2월</li>
                <li className="calender_item" onClick={onClickItem}>3월</li>
                <li className="calender_item" onClick={onClickItem}>4월</li>
                <li className="calender_item" onClick={onClickItem}>5월</li>
                <li className="calender_item" onClick={onClickItem}>6월</li>
                <li className="calender_item" onClick={onClickItem}>7월</li>
                <li className="calender_item" onClick={onClickItem}>8월</li>
                <li className="calender_item" onClick={onClickItem}>9월</li>
                <li className="calender_item" onClick={onClickItem}>10월</li>
                <li className="calender_item" onClick={onClickItem}>11월</li>
                <li className="calender_item" onClick={onClickItem}>12월</li> */}
              </ul>
            </div>
          </div>  
        </div>          
        
        <div className='thema_class'>
          <div className='thema_box'>#테마</div>
          <div className='thema_box'>#테마</div>
          <div className='thema_box'>#테마</div>
          <div className='thema_box'>#테마</div>
        </div>
      </div>
  );

};// Festval_search_detauls close


export default Festval_serch_details;
